if (all(#Lobby #PresenceSensor).presenceSensor_presence == false) {
hold_ticks = hold_ticks + 1
    if (hold_ticks >= 60) {
(#Speaker).speaker_speak("Is anyone there")
        break
}
}
else {
hold_ticks = 0
}
n := 0
if (n >= 4) {
break
}
(#Speaker).speaker_speak("Is anyone there")
n = n + 1

